    atomic_with_ghost!(
    this.inner.lock => compare_exchange(UPGRADEABLE_READER | BEING_UPGRADED, WRITER | UPGRADEABLE_READER);
    update prev -> next;
    returning res;
    ghost g => {
        lemma_consts_properties();
        lemma_consts_properties_value(prev);
        lemma_consts_properties_prev_next(prev, next);
        if res.is_ok() {
            // SUCCESS: prev == UPGRADEABLE_READER | BEING_UPGRADED, next == WRITER | UPGRADEABLE_READER
            // From invariant with prev:
            //   active_upgrade_guard = true (upreader_guard_token is None in lock)
            //   !(active_upgrade_guard && pending_failed_upread_attempt) => upread_retract_token is Some
            //   total_reader_bits = 0 => read_guard_token is full

            // 1. Take out upread_retract_token (must be Some due to invariant)
            let tracked u_token_opt = g.upread_retract_token;
            g.upread_retract_token = None;
            let tracked u_token = u_token_opt.tracked_unwrap();
            retract_upgrade_token = Some(u_token);

            // 2. Take the full CountResource from read_guard_token
            let tracked left_cr = g.read_guard_token.tracked_take_left();
            let tracked (read_perm_val, empty_left_cr) = left_cr.take_resource();
            // read_perm_val: ReadPerm<T> = (HalfPerm<T>, OneLeftKnowledge<...>)
            let tracked (half_perm_read, left_knowledge) = read_perm_val;

            // 3. Set read_guard_token to Right(EmptyCount)
            g.read_guard_token = Sum::Right(empty_left_cr);

            // 4. Join upread_guard_token (OneLeftOwner, frac=1) into core_token (Left, frac=1)
            g.core_token.join_one_left_owner(upread_guard_token);
            // core_token: Left, frac=2, is_resource_owner, has_resource=HalfPerm

            // 5. Join OneLeftKnowledge into core_token to reach frac=3
            g.core_token.join_one_left_knowledge(left_knowledge);
            // core_token: Left, frac=3, is_resource_owner, has_resource=HalfPerm

            // 6. Take the HalfPerm from core_token
            let tracked half_perm_guard = g.core_token.take_resource_left();
            // core_token: Left, frac=3, is_resource_owner, has_no_resource

            // 7. Combine the two HalfPerms to get full Count<PointsTo<T>, 2> (frac=2)
            let tracked mut combined_perm = half_perm_guard;
            combined_perm.combine(half_perm_read);
