    // We hold retract_upgrade_token (UniqueToken with id == upread_retract_token_id).
    // If g.upread_retract_token is Some, then both tokens have id == upread_retract_token_id,
    // but validate_with_other proves they must have distinct ids - contradiction.
    let tracked mut retract_token_unwrapped = retract_upgrade_token.tracked_unwrap();
    match &g.upread_retract_token {
        Some(lock_token) => {
            retract_token_unwrapped.validate_with_other(lock_token);
            // retract_token_unwrapped.id() != lock_token.id()
            // but both have id == upread_retract_token_id - contradiction
            assert(false);
        }
        None => {}
